import csv
rows=list(csv.reader(open('data/orders.csv',encoding='utf-8')))[1:]
from collections import defaultdict
g=defaultdict(list)
for r in rows:
    if len(r)==5: g[r[0]].append(r)
dup={k:v for k,v in g.items() if len(v)>1}
print('重复单号数:',len(dup),'| 出现次数分布:',sorted({len(v) for v in dup.values()}))
diff={k:[x for x in v if x!=v[0]] for k,v in dup.items()}
diff={k:v for k,v in diff.items() if v}
print('同号但内容不一致的:',len(diff))
for k,v in list(diff.items())[:5]: print(' ',k,v)
